public class Test {
    public static void main(String[] a) {
        BankAccount acct = new BankAccount(100);
        boolean[] ok = new boolean[2];
        String out1 = capture(() -> ok[0] = acct.withdraw(50));
        String out2 = capture(() -> ok[1] = acct.withdraw(500));
        if (!(out1.contains("Withdrawing 50"))) throw new AssertionError("missing log for 50");
        if (!(out2.contains("Withdrawing 500"))) throw new AssertionError("missing log for 500");
        if (!(ok[0] && !ok[1] && acct.getBalance() == 50)) throw new AssertionError("behavior changed");
        System.out.println("PASS");
    }

    static String capture(Runnable r) {
        java.io.PrintStream original = System.out;
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        System.setOut(new java.io.PrintStream(buf, true));
        try { r.run(); } finally { System.setOut(original); }
        return buf.toString();
    }
}
